'use client'

import { useId, useState } from 'react'
import type { KeyboardEvent, ReactNode } from 'react'
import { cn } from '@/lib/utils'

export type MacAccordionItem = {
  id: string
  title: string
  content: ReactNode
  disabled?: boolean
}

type MacAccordionProps = {
  items: MacAccordionItem[]
  type?: 'single' | 'multiple'
  defaultValue?: string[]
  className?: string
}

export function MacAccordion({ items, type = 'single', defaultValue = [], className }: MacAccordionProps) {
  const [open, setOpen] = useState<string[]>(defaultValue)
  const baseId = useId()

  function toggle(id: string) {
    setOpen((current) => {
      if (current.includes(id)) return current.filter((value) => value !== id)
      return type === 'single' ? [id] : [...current, id]
    })
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const triggers = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('[data-accordion-trigger]:not(:disabled)')]
    const index = triggers.findIndex((trigger) => trigger === document.activeElement)
    if (index < 0) return
    const target =
      event.key === 'ArrowDown'
        ? triggers[(index + 1) % triggers.length]
        : event.key === 'ArrowUp'
          ? triggers[(index - 1 + triggers.length) % triggers.length]
          : event.key === 'Home'
            ? triggers[0]
            : event.key === 'End'
              ? triggers[triggers.length - 1]
              : undefined
    if (target) {
      event.preventDefault()
      target.focus()
    }
  }

  return (
    <div onKeyDown={onKeyDown} className={cn('flex flex-col gap-2 font-rt-mono text-[12px] text-mac-ink', className)}>
      {items.map((item) => {
        const isOpen = open.includes(item.id)
        const triggerId = `${baseId}-trigger-${item.id}`
        const panelId = `${baseId}-panel-${item.id}`
        return (
          <div key={item.id}>
            <button
              id={triggerId}
              type="button"
              data-accordion-trigger=""
              aria-expanded={isOpen}
              aria-controls={panelId}
              disabled={item.disabled}
              onClick={() => toggle(item.id)}
              className={cn(
                'flex w-full items-center gap-2 border-2 border-mac-ink bg-mac-paper px-2 py-0.5 text-left font-bold select-none',
                'hover:bg-mac-hover aria-expanded:bg-mac-ink aria-expanded:text-mac-paper',
                'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-mac-ink',
                'disabled:cursor-not-allowed disabled:border-mac-dim disabled:text-mac-dim',
              )}
            >
              <svg aria-hidden="true" viewBox="0 0 8 8" className={cn('size-2 shrink-0 fill-current', isOpen && 'rotate-90')}>
                <path d="M1.5 0.5v7L7 4z" />
              </svg>
              {item.title}
            </button>
            <div
              id={panelId}
              role="region"
              aria-labelledby={triggerId}
              hidden={!isOpen}
              className="border-2 border-t-0 border-mac-ink bg-mac-paper p-2.5 leading-snug"
            >
              {item.content}
            </div>
          </div>
        )
      })}
    </div>
  )
}

import { cn } from '@/lib/utils'

export type MacBreadcrumbItem = {
  label: string
  href?: string
}

type MacBreadcrumbProps = {
  items: MacBreadcrumbItem[]
  label?: string
  className?: string
}

export function MacBreadcrumb({ items, label = 'Breadcrumb', className }: MacBreadcrumbProps) {
  return (
    <nav aria-label={label} className={className}>
      <ol className="flex flex-wrap items-center font-rt-mono text-[12px] text-mac-ink">
        {items.map((item, index) => {
          const isLast = index === items.length - 1
          return (
            <li key={`${item.label}-${index}`} className="flex items-center">
              {isLast || !item.href ? (
                <span aria-current={isLast ? 'page' : undefined} className={cn(isLast && 'font-bold')}>
                  {item.label}
                </span>
              ) : (
                <a
                  href={item.href}
                  className="underline underline-offset-2 hover:bg-mac-ink hover:text-mac-paper focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-mac-ink"
                >
                  {item.label}
                </a>
              )}
              {isLast ? null : (
                <span aria-hidden="true" className="px-1">
                  :
                </span>
              )}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}

import type { ButtonHTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

type MacButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & { isDefault?: boolean }

export function MacButton({ isDefault, className, children, type = 'button', ...props }: MacButtonProps) {
  return (
    <button
      type={type}
      className={cn(
        'rounded-[10px] border-2 border-mac-ink bg-mac-paper px-4 py-0.5 font-rt-mono text-[12px] font-semibold text-mac-ink',
        'transition-colors hover:bg-mac-hover active:bg-mac-ink active:text-mac-paper',
        'focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-mac-ink',
        'disabled:cursor-not-allowed disabled:border-dashed disabled:text-mac-dim disabled:hover:bg-mac-paper',
        isDefault && 'shadow-[0_0_0_2px_var(--color-mac-paper),0_0_0_4px_var(--color-mac-ink)]',
        className,
      )}
      {...props}
    >
      {children}
    </button>
  )
}

'use client'

import { useEffect, useId, useRef, useState } from 'react'
import type { KeyboardEvent } from 'react'
import { cn } from '@/lib/utils'

export type MacMenuItem =
  | { separator: true }
  | { label: string; shortcut?: string; disabled?: boolean; onSelect?: () => void }

type MacDropdownMenuProps = {
  label: string
  items: MacMenuItem[]
  align?: 'start' | 'end'
  className?: string
}

const enabledIndices = (items: MacMenuItem[]) =>
  items.flatMap((item, index) => ('separator' in item || item.disabled ? [] : [index]))

export function MacDropdownMenu({ label, items, align = 'start', className }: MacDropdownMenuProps) {
  const [open, setOpen] = useState(false)
  const rootRef = useRef<HTMLDivElement>(null)
  const triggerRef = useRef<HTMLButtonElement>(null)
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([])
  const initialFocus = useRef<'first' | 'last'>('first')
  const menuId = useId()

  useEffect(() => {
    if (!open) return
    const list = enabledIndices(items)
    const target = initialFocus.current === 'last' ? list[list.length - 1] : list[0]
    itemRefs.current[target]?.focus()
    const onPointerDown = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    return () => document.removeEventListener('pointerdown', onPointerDown)
  }, [open, items])

  function close(refocus: boolean) {
    setOpen(false)
    if (refocus) triggerRef.current?.focus()
  }

  function openWith(position: 'first' | 'last') {
    initialFocus.current = position
    setOpen(true)
  }

  function onTriggerKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      openWith(event.key === 'ArrowDown' ? 'first' : 'last')
    }
  }

  function onMenuKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const list = enabledIndices(items)
    const position = list.indexOf(itemRefs.current.findIndex((el) => el === document.activeElement))
    const focusAt = (index: number | undefined) => {
      if (index !== undefined) itemRefs.current[index]?.focus()
    }
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        focusAt(list[(position + 1) % list.length])
        break
      case 'ArrowUp':
        event.preventDefault()
        focusAt(position <= 0 ? list[list.length - 1] : list[position - 1])
        break
      case 'Home':
        event.preventDefault()
        focusAt(list[0])
        break
      case 'End':
        event.preventDefault()
        focusAt(list[list.length - 1])
        break
      case 'Escape':
        event.preventDefault()
        close(true)
        break
      case 'Tab':
        close(false)
        break
    }
  }

  return (
    <div ref={rootRef} className={cn('relative inline-block font-rt-mono text-[12px] text-mac-ink', className)}>
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? menuId : undefined}
        onClick={() => (open ? close(false) : openWith('first'))}
        onKeyDown={onTriggerKeyDown}
        className={cn(
          'flex items-center gap-3 border-2 border-mac-ink bg-mac-paper px-3 py-0.5 font-semibold shadow-[2px_2px_0_var(--color-mac-ink)] select-none',
          'hover:bg-mac-hover aria-expanded:bg-mac-ink aria-expanded:text-mac-paper',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-mac-ink',
        )}
      >
        {label}
        <svg aria-hidden="true" viewBox="0 0 8 8" className="size-2 fill-current">
          <path d="M0 2h8L4 7z" />
        </svg>
      </button>
      {open ? (
        <div
          id={menuId}
          role="menu"
          aria-label={label}
          onKeyDown={onMenuKeyDown}
          className={cn(
            'absolute top-full z-20 min-w-44 border-2 border-mac-ink bg-mac-paper py-0.5 shadow-[3px_3px_0_var(--color-mac-ink)]',
            align === 'end' ? 'right-0' : 'left-0',
          )}
        >
          {items.map((item, index) =>
            'separator' in item ? (
              <div key={`separator-${index}`} role="separator" className="my-0.5 border-t border-dashed border-mac-ink" />
            ) : (
              <button
                key={item.label}
                ref={(element) => {
                  itemRefs.current[index] = element
                }}
                type="button"
                role="menuitem"
                tabIndex={-1}
                disabled={item.disabled}
                onMouseEnter={(event) => event.currentTarget.focus()}
                onClick={() => {
                  item.onSelect?.()
                  close(true)
                }}
                className={cn(
                  'flex w-full items-center justify-between gap-6 px-3 py-0.5 text-left',
                  'focus-visible:bg-mac-ink focus-visible:text-mac-paper focus-visible:outline-none',
                  'disabled:cursor-not-allowed disabled:text-mac-dim',
                )}
              >
                <span>{item.label}</span>
                {item.shortcut ? <span>{item.shortcut}</span> : null}
              </button>
            ),
          )}
        </div>
      ) : null}
    </div>
  )
}

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

export function MacProgress({ value, label, className }: { value: number; label: string; className?: string }) {
  const clamped = Math.min(100, Math.max(0, value))
  return (
    <div
      role="progressbar"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(clamped)}
      className={cn('h-4 border-2 border-mac-ink bg-mac-paper p-px', className)}
    >
      <div className="h-full bg-mac-ink" style={{ width: `${clamped}%` }} />
    </div>
  )
}

type MacAlertProps = {
  label: string
  children: ReactNode
  actions?: ReactNode
  className?: string
}

export function MacAlert({ label, children, actions, className }: MacAlertProps) {
  return (
    <div
      role="alertdialog"
      aria-label={label}
      className={cn('border-2 border-mac-ink bg-mac-paper p-0.5 shadow-[3px_3px_0_var(--color-mac-ink)]', className)}
    >
      <div className="border-2 border-mac-ink p-3 font-rt-mono text-[12px] text-mac-ink">
        <div className="flex gap-3">
          <svg viewBox="0 0 32 32" aria-hidden="true" className="size-8 shrink-0">
            <path d="M16 3 30 28H2Z" fill="var(--color-mac-paper)" stroke="var(--color-mac-ink)" strokeWidth="2.5" strokeLinejoin="round" />
            <path d="M16 12v8M16 23.5v1" stroke="var(--color-mac-ink)" strokeWidth="3" />
          </svg>
          <div className="leading-snug">{children}</div>
        </div>
        {actions ? <div className="mt-3 flex justify-end gap-4 pr-1">{actions}</div> : null}
      </div>
    </div>
  )
}

import { useId } from 'react'
import type { InputHTMLAttributes, ReactNode, TextareaHTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

type MacInputProps = InputHTMLAttributes<HTMLInputElement> & { label?: string }

export function MacInput({ label, className, id, ...props }: MacInputProps) {
  const autoId = useId()
  const inputId = id ?? autoId
  return (
    <div className="flex flex-col gap-1 font-rt-mono text-[12px] text-mac-ink">
      {label ? (
        <label htmlFor={inputId} className="font-semibold">
          {label}
        </label>
      ) : null}
      <input
        id={inputId}
        className={cn(
          'h-6 border-2 border-mac-ink bg-mac-paper px-1.5 text-[12px] text-mac-ink placeholder:text-mac-dim',
          'disabled:border-dashed disabled:text-mac-dim',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-mac-ink',
          className,
        )}
        {...props}
      />
    </div>
  )
}

type MacTextareaProps = TextareaHTMLAttributes<HTMLTextAreaElement> & { label?: string }

export function MacTextarea({ label, className, id, rows = 4, ...props }: MacTextareaProps) {
  const autoId = useId()
  const textareaId = id ?? autoId
  return (
    <div className="flex flex-col gap-1 font-rt-mono text-[12px] text-mac-ink">
      {label ? (
        <label htmlFor={textareaId} className="font-semibold">
          {label}
        </label>
      ) : null}
      <textarea
        id={textareaId}
        rows={rows}
        className={cn(
          'mac-scroll min-h-16 resize-y border-2 border-mac-ink bg-mac-paper p-1.5 text-[12px] leading-snug text-mac-ink placeholder:text-mac-dim',
          'disabled:border-dashed disabled:text-mac-dim',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-mac-ink',
          className,
        )}
        {...props}
      />
    </div>
  )
}

type ToggleProps = Omit<InputHTMLAttributes<HTMLInputElement>, 'type'> & { label: ReactNode }

const toggleLabel =
  'flex cursor-pointer items-center gap-2 py-0.5 font-rt-mono text-[12px] text-mac-ink has-disabled:cursor-not-allowed has-disabled:text-mac-dim'

const toggleBox =
  'flex size-3.5 shrink-0 items-center justify-center border-2 border-mac-ink bg-mac-paper peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-mac-ink peer-disabled:border-dashed'

export function MacCheckbox({ label, className, ...props }: ToggleProps) {
  return (
    <label className={cn(toggleLabel, className)}>
      <input type="checkbox" className="peer sr-only" {...props} />
      <span aria-hidden="true" className={cn(toggleBox, 'peer-checked:[&_svg]:scale-100')}>
        <svg viewBox="0 0 10 10" className="size-2.5 scale-0">
          <path d="M1 1l8 8M9 1L1 9" stroke="var(--color-mac-ink)" strokeWidth="1.5" />
        </svg>
      </span>
      <span>{label}</span>
    </label>
  )
}

export function MacRadio({ label, className, ...props }: ToggleProps) {
  return (
    <label className={cn(toggleLabel, className)}>
      <input type="radio" className="peer sr-only" {...props} />
      <span aria-hidden="true" className={cn(toggleBox, 'rounded-full peer-checked:[&_i]:scale-100')}>
        <i className="block size-1.5 scale-0 rounded-full bg-mac-ink" />
      </span>
      <span>{label}</span>
    </label>
  )
}

export function MacGroup({
  legend,
  children,
  className,
}: {
  legend: string
  children: ReactNode
  className?: string
}) {
  return (
    <fieldset className={cn('border-2 border-mac-ink px-3 pt-1 pb-2 font-rt-mono text-[12px] text-mac-ink', className)}>
      <legend className="bg-mac-paper px-1.5 font-semibold">{legend}</legend>
      {children}
    </fieldset>
  )
}

import type { LabelHTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

type MacLabelProps = LabelHTMLAttributes<HTMLLabelElement> & {
  required?: boolean
}

export function MacLabel({ required, className, children, ...props }: MacLabelProps) {
  return (
    <label className={cn('inline-flex items-baseline gap-1 font-rt-mono text-[12px] font-bold text-mac-ink', className)} {...props}>
      {children}
      {required ? <span aria-hidden="true">*</span> : null}
    </label>
  )
}

type MacSeparatorProps = {
  orientation?: 'horizontal' | 'vertical'
  variant?: 'solid' | 'dashed'
  decorative?: boolean
  className?: string
}

export function MacSeparator({ orientation = 'horizontal', variant = 'solid', decorative = false, className }: MacSeparatorProps) {
  const horizontal = orientation === 'horizontal'
  return (
    <div
      role={decorative ? 'none' : 'separator'}
      aria-orientation={decorative || horizontal ? undefined : 'vertical'}
      className={cn(
        horizontal ? 'w-full border-t-2' : 'h-full min-h-4 border-l-2',
        variant === 'dashed' ? 'border-dashed' : 'border-solid',
        'border-mac-ink',
        className,
      )}
    />
  )
}

'use client'

import { useId, useRef, useState } from 'react'
import type { KeyboardEvent } from 'react'
import { cn } from '@/lib/utils'

export type MacListboxOption = { value: string; label: string; disabled?: boolean }

type MacListboxProps = {
  options: MacListboxOption[]
  label: string
  multiple?: boolean
  value?: string[]
  defaultValue?: string[]
  onValueChange?: (value: string[]) => void
  className?: string
  listClassName?: string
}

export function MacListbox({
  options,
  label,
  multiple = false,
  value,
  defaultValue = [],
  onValueChange,
  className,
  listClassName,
}: MacListboxProps) {
  const baseId = useId()
  const labelId = `${baseId}-label`
  const listRef = useRef<HTMLDivElement>(null)
  const [internal, setInternal] = useState(defaultValue)
  const selected = value ?? internal
  const [active, setActive] = useState(() => {
    const index = options.findIndex((option) => selected.includes(option.value) && !option.disabled)
    return index >= 0 ? index : Math.max(0, options.findIndex((option) => !option.disabled))
  })

  const optionId = (index: number) => `${baseId}-option-${index}`

  function commit(next: string[]) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function choose(index: number) {
    const option = options[index]
    if (!option || option.disabled) return
    setActive(index)
    if (multiple) {
      commit(selected.includes(option.value) ? selected.filter((v) => v !== option.value) : [...selected, option.value])
    } else {
      commit([option.value])
    }
  }

  function step(from: number, direction: 1 | -1) {
    let index = from + direction
    while (index >= 0 && index < options.length && options[index].disabled) index += direction
    return index >= 0 && index < options.length ? index : from
  }

  function moveTo(index: number) {
    if (index < 0 || index >= options.length) return
    setActive(index)
    listRef.current?.children[index]?.scrollIntoView({ block: 'nearest' })
    if (!multiple) choose(index)
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    switch (event.key) {
      case 'ArrowDown':
      case 'ArrowUp':
        event.preventDefault()
        moveTo(step(active, event.key === 'ArrowDown' ? 1 : -1))
        break
      case 'Home':
        event.preventDefault()
        moveTo(step(-1, 1))
        break
      case 'End':
        event.preventDefault()
        moveTo(step(options.length, -1))
        break
      case ' ':
      case 'Enter':
        event.preventDefault()
        choose(active)
        break
    }
  }

  return (
    <div className={cn('flex flex-col gap-1 font-rt-mono text-[12px] text-mac-ink', className)}>
      <span id={labelId} className="font-semibold">
        {label}
      </span>
      <div
        ref={listRef}
        role="listbox"
        aria-labelledby={labelId}
        aria-multiselectable={multiple || undefined}
        aria-activedescendant={optionId(active)}
        tabIndex={0}
        onKeyDown={onKeyDown}
        className={cn(
          'group mac-scroll h-32 overflow-auto border-2 border-mac-ink bg-mac-paper',
          'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-mac-ink',
          listClassName,
        )}
      >
        {options.map((option, index) => {
          const isSelected = selected.includes(option.value)
          return (
            <div
              key={option.value}
              id={optionId(index)}
              role="option"
              aria-selected={isSelected}
              aria-disabled={option.disabled || undefined}
              onClick={() => choose(index)}
              className={cn(
                'cursor-pointer px-2 py-0.5 select-none',
                isSelected ? 'bg-mac-ink text-mac-paper' : 'hover:bg-mac-hover',
                index === active &&
                  'group-focus-visible:outline-1 group-focus-visible:-outline-offset-3 group-focus-visible:outline-dotted group-focus-visible:outline-current',
                option.disabled && 'cursor-not-allowed text-mac-dim hover:bg-transparent',
              )}
            >
              {option.label}
            </div>
          )
        })}
      </div>
    </div>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'

export type MacMenu = { label: string; items: string[] }

type MacMenubarProps = {
  menus: MacMenu[]
  label?: string
  className?: string
  onSelect?: (menu: string, item: string) => void
}

export function MacMenubar({ menus, label = 'Menu', className, onSelect }: MacMenubarProps) {
  const [open, setOpen] = useState<number | null>(null)
  const ref = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (open === null) return
    const onPointerDown = (event: PointerEvent) => {
      if (!ref.current?.contains(event.target as Node)) setOpen(null)
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(null)
    }
    document.addEventListener('pointerdown', onPointerDown)
    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('pointerdown', onPointerDown)
      document.removeEventListener('keydown', onKeyDown)
    }
  }, [open])

  return (
    <div
      ref={ref}
      role="menubar"
      aria-label={label}
      className={cn(
        'flex items-center gap-1 border-b-2 border-mac-ink bg-mac-paper px-2 font-rt-mono text-[12px] font-semibold text-mac-ink',
        className,
      )}
    >
      <span aria-hidden="true" className="mr-2 size-3 rounded-full bg-mac-ink" />
      {menus.map((menu, index) => {
        const isOpen = open === index
        return (
          <div key={menu.label} role="none" className="relative">
            <button
              type="button"
              role="menuitem"
              aria-haspopup="menu"
              aria-expanded={isOpen}
              onClick={() => setOpen(isOpen ? null : index)}
              onMouseEnter={() => open !== null && setOpen(index)}
              className={cn(
                'px-2 py-0.5 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-mac-ink',
                isOpen ? 'bg-mac-ink text-mac-paper' : 'hover:bg-mac-hover',
              )}
            >
              {menu.label}
            </button>
            {isOpen ? (
              <ul
                role="menu"
                aria-label={menu.label}
                className="absolute top-full left-0 z-10 min-w-36 border-2 border-mac-ink bg-mac-paper py-0.5 font-normal shadow-[3px_3px_0_var(--color-mac-ink)]"
              >
                {menu.items.map((item) => (
                  <li key={item} role="none">
                    <button
                      type="button"
                      role="menuitem"
                      onClick={() => {
                        onSelect?.(menu.label, item)
